"""Pipeline DB persistence operations."""

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

_CHECKPOINT_DIR = Path("./data/checkpoints")


class PipelinePersistence:
    """Handles all database writes for pipeline runs."""

    def __init__(self):
        self.warnings: list[str] = []

    def get_warnings(self) -> list[str]:
        return self.warnings.copy()

    def create_run_record(self, domain: str, params: dict, session_id: str | None = None) -> int | None:
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                db_run = crud.create_pipeline_run(
                    session,
                    domain=domain,
                    status="running",
                    current_stage="initializing",
                    config_json=json.dumps(params),
                    session_id=session_id,
                )
                return db_run.id
        except Exception as e:
            logger.warning("Failed to create DB run record: %s", e)
            self.warnings.append(f"create_run_record: {e}")
            return None

    def persist_gaps(self, result, db_run_id: int | None) -> None:
        if not db_run_id or not result.gaps:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                for gap in result.gaps:
                    crud.create_gap(
                        session,
                        title=gap.title,
                        description=gap.description,
                        gap_type=gap.gap_type,
                        confidence=gap.confidence,
                        potential_impact=gap.potential_impact,
                        pipeline_run_id=db_run_id,
                    )
        except Exception as e:
            logger.warning("Failed to persist gaps: %s", e)
            self.warnings.append(f"persist_gaps: {e}")

    def persist_papers(self, papers: list, db_run_id: int | None) -> None:
        if not db_run_id:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                for paper in papers:
                    if not crud.get_paper_by_source_id(session, paper.id):
                        crud.create_paper(
                            session,
                            source_id=paper.id,
                            source=paper.source,
                            title=paper.title,
                            abstract=paper.abstract,
                            authors=json.dumps([a.name for a in paper.authors])
                            if paper.authors
                            else "[]",
                            year=paper.year,
                            venue=paper.venue,
                            citation_count=paper.citation_count,
                            url=paper.url,
                            doi=paper.doi,
                            arxiv_id=paper.arxiv_id,
                            keywords=json.dumps(paper.keywords) if paper.keywords else "[]",
                        )
        except Exception as e:
            logger.warning("Failed to persist papers: %s", e)
            self.warnings.append(f"persist_papers: {e}")

    def persist_ideas(self, result, db_run_id: int | None) -> None:
        if not db_run_id or not result.ideas:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                for i, idea in enumerate(result.ideas):
                    nov = result.novelty_reports.get(i)
                    feas = result.feasibility_reports.get(i)
                    db_idea = crud.create_idea(
                        session,
                        title=idea.title,
                        problem_statement=idea.problem_statement,
                        proposed_method=idea.proposed_method,
                        expected_contributions=idea.expected_contributions,
                        domain=idea.domain,
                        source_gap_ids=json.dumps(idea.source_gap_ids) if idea.source_gap_ids else None,
                        pipeline_run_id=db_run_id,
                    )
                    if nov or feas:
                        crud.update_idea_scores(
                            session,
                            db_idea.id,
                            novelty_score=nov.overall_score if nov else None,
                            feasibility_score=feas.overall_score if feas else None,
                            novelty_report=json.dumps(
                                {
                                    "method_novelty": nov.method_novelty,
                                    "problem_novelty": nov.problem_novelty,
                                    "domain_transfer": nov.domain_transfer,
                                    "combination_novelty": nov.combination_novelty,
                                    "novelty_arguments": nov.novelty_arguments,
                                }
                            )
                            if nov
                            else None,
                            feasibility_report=json.dumps(
                                {
                                    "data_availability": feas.data_availability,
                                    "computational_requirements": feas.computational_requirements,
                                    "methodological_complexity": feas.methodological_complexity,
                                    "evaluation_plan": feas.evaluation_plan,
                                    "reasoning": feas.reasoning,
                                    "estimated_timeline": feas.estimated_timeline,
                                }
                            )
                            if feas
                            else None,
                        )
        except Exception as e:
            logger.warning("Failed to persist ideas: %s", e)
            self.warnings.append(f"persist_ideas: {e}")

    def persist_proposals(self, result, db_run_id: int | None) -> None:
        if not db_run_id or not result.proposals:
            return
        try:
            from sqlalchemy import select

            from backend.db import crud
            from backend.db.database import get_session
            from backend.db.models import Idea

            with get_session() as session:
                for i, proposal in result.proposals.items():
                    idea = result.ideas[i] if i < len(result.ideas) else None
                    if idea:
                        db_idea_row = session.execute(
                            select(Idea).where(
                                Idea.title == idea.title,
                                Idea.pipeline_run_id == db_run_id,
                            )
                        ).scalar_one_or_none()
                        if db_idea_row:
                            sections_to_store = {
                                k: v for k, v in proposal.sections.items() if k != "validated_text"
                            }
                            crud.create_proposal(
                                session,
                                idea_id=db_idea_row.id,
                                content_md=proposal.to_markdown(),
                                references_json=json.dumps(proposal.sections.get("references", [])),
                                sections_json=json.dumps(sections_to_store),
                            )
        except Exception as e:
            logger.warning("Failed to persist proposals: %s", e)
            self.warnings.append(f"persist_proposals: {e}")

    def mark_run_failed(self, db_run_id: int | None, message: str) -> None:
        if not db_run_id:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                crud.update_pipeline_run(session, db_run_id, status="failed", error_message=message)
        except Exception as e:
            logger.warning("Failed to mark DB run as failed: %s", e)
            self.warnings.append(f"mark_run_failed: {e}")

    def mark_run_completed(self, db_run_id: int | None) -> None:
        if not db_run_id:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                crud.update_pipeline_run(session, db_run_id, status="completed")
        except Exception as e:
            logger.warning("Failed to mark DB run as completed: %s", e)
            self.warnings.append(f"mark_run_completed: {e}")

    # ── Checkpoint persistence (durable execution) ─────────────────

    def save_checkpoint(self, checkpoint: "RunCheckpoint") -> None:
        """Save a run checkpoint to disk."""
        try:
            _CHECKPOINT_DIR.mkdir(parents=True, exist_ok=True)
            path = _CHECKPOINT_DIR / f"{checkpoint.run_id}.json"
            path.write_text(checkpoint.to_json(), encoding="utf-8")
            logger.info("Checkpoint saved: %s", checkpoint.run_id)
        except Exception as e:
            logger.warning("Failed to save checkpoint: %s", e)
            self.warnings.append(f"save_checkpoint: {e}")

    def load_checkpoint(self, run_id: str) -> "RunCheckpoint | None":
        """Load a run checkpoint from disk."""
        try:
            path = _CHECKPOINT_DIR / f"{run_id}.json"
            if not path.exists():
                return None
            from backend.pipeline.execution.run_state import RunCheckpoint
            return RunCheckpoint.from_json(path.read_text(encoding="utf-8"))
        except Exception as e:
            logger.warning("Failed to load checkpoint for %s: %s", run_id, e)
            self.warnings.append(f"load_checkpoint: {e}")
            return None

    def list_checkpoints(self) -> list[dict]:
        """List all resumable checkpoints."""
        results = []
        if not _CHECKPOINT_DIR.exists():
            return results
        for path in _CHECKPOINT_DIR.glob("*.json"):
            try:
                from backend.pipeline.execution.run_state import RunCheckpoint
                cp = RunCheckpoint.from_json(path.read_text(encoding="utf-8"))
                results.append({
                    "run_id": cp.run_id,
                    "state": cp.state.value,
                    "completed_stages": sum(1 for s in cp.stages if s.status.value == "completed"),
                    "total_stages": len(cp.stages),
                })
            except Exception:
                pass
        return results

    # ---- State Reconstruction for Resume ----

    def get_run_by_uuid(self, run_id: str) -> Any | None:
        """Look up a PipelineRun by its UUID string."""
        from backend.db.crud import list_pipeline_runs
        with self._session() as session:
            runs = list_pipeline_runs(session, limit=100)
            for run in runs:
                if str(run.id) == run_id or run_id.endswith(str(run.id)):
                    return run
        return None

    def load_gaps(self, run_db_id: int) -> list:
        """Load ResearchGap objects from database for a pipeline run."""
        from backend.db.crud import get_pipeline_run
        with self._session() as session:
            run = get_pipeline_run(session, run_db_id)
            if not run:
                return []
            from backend.pipeline.gap_analysis.models import ResearchGap
            gaps = []
            for gap_db in getattr(run, "gaps", []):
                gaps.append(ResearchGap(
                    title=gap_db.title,
                    description=gap_db.description,
                    gap_type=gap_db.gap_type,
                    confidence=gap_db.confidence,
                    potential_impact=getattr(gap_db, "potential_impact", ""),
                ))
            return gaps

    def load_ideas(self, run_db_id: int) -> list:
        """Load ResearchIdea objects from database for a pipeline run."""
        from backend.db.crud import get_pipeline_run
        with self._session() as session:
            run = get_pipeline_run(session, run_db_id)
            if not run:
                return []
            from backend.pipeline.generation.models import ResearchIdea
            ideas = []
            for idea_db in getattr(run, "ideas", []):
                ideas.append(ResearchIdea(
                    title=idea_db.title,
                    problem_statement=getattr(idea_db, "problem_statement", ""),
                    proposed_method=getattr(idea_db, "proposed_method", ""),
                    domain=getattr(idea_db, "domain", "AI/NLP"),
                    score=getattr(idea_db, "overall_score", 0.0) or 0.0,
                ))
            return ideas

"""Epistemic truth maintenance via OpenNARS-inspired truth calculus.

Each knowledge assertion (gap, idea, relationship) carries a TruthValue
with frequency (proportion of supporting evidence) and confidence
(total evidence relative to evidential horizon). New evidence revises
existing truth via weighted averaging rather than overwriting.
"""

from pydantic import BaseModel


class TruthValue(BaseModel):
    """OpenNARS-inspired evidential truth value.

    frequency = P(proposition is true | evidence)
    confidence = P(evidence is sufficient)
    """

    frequency: float = 0.5
    confidence: float = 0.5
    evidence_count: int = 0
    propagation_debt: float = 0.0  # How stale downstream consumers are

    @property
    def expectation(self) -> float:
        """Weighted expectation: frequency * confidence."""
        return self.frequency * self.confidence

    def revise(self, other: "TruthValue") -> "TruthValue":
        """Weighted revision when new evidence arrives.

        Uses the OpenNARS revision rule: weights are derived from
        confidence values, and the new truth is a weighted average.
        """
        w1 = self.confidence / (1 - self.confidence + 1e-10)
        w2 = other.confidence / (1 - other.confidence + 1e-10)
        total_w = w1 + w2
        if total_w == 0:
            return TruthValue(
                frequency=0.5,
                confidence=0.5,
                evidence_count=self.evidence_count + other.evidence_count,
            )
        new_freq = (w1 * self.frequency + w2 * other.frequency) / total_w
        new_conf = total_w / (total_w + 1)
        # Propagation debt: how much truth changed, flagging downstream consumers as stale
        debt = abs(new_freq - self.frequency) * self.confidence
        return TruthValue(
            frequency=max(0.0, min(1.0, new_freq)),
            confidence=min(0.99, new_conf),
            evidence_count=self.evidence_count + other.evidence_count + 1,
            propagation_debt=debt,
        )

    def decay(self, rate: float = 0.99) -> "TruthValue":
        """Temporal truth decay. Confidence decreases over time."""
        return TruthValue(
            frequency=self.frequency,
            confidence=self.confidence * rate,
            evidence_count=self.evidence_count,
        )

    def settle_debt(self) -> "TruthValue":
        """Mark propagation debt as resolved after downstream update."""
        return TruthValue(
            frequency=self.frequency,
            confidence=self.confidence,
            evidence_count=self.evidence_count,
            propagation_debt=0.0,
        )

    @staticmethod
    def from_observation(frequency: float = 1.0) -> "TruthValue":
        """Create a TruthValue from a single observation."""
        return TruthValue(
            frequency=frequency,
            confidence=0.5,
            evidence_count=1,
        )

    @staticmethod
    def initial() -> "TruthValue":
        """Default truth value for new assertions with no prior evidence."""
        return TruthValue(
            frequency=0.5,
            confidence=0.5,
            evidence_count=0,
        )

"""CRUD operations for the metadata database."""

import json
from collections.abc import Sequence

from sqlalchemy import select, func, case, desc, asc
from sqlalchemy.orm import Session

from backend.db.models import Idea, Paper, PipelineRun, Proposal, ResearchGapDB

# --- Papers ---


def create_paper(session: Session, **kwargs) -> Paper:
    paper = Paper(**kwargs)
    session.add(paper)
    session.commit()
    session.refresh(paper)
    return paper


def get_paper(session: Session, paper_id: int) -> Paper | None:
    return session.get(Paper, paper_id)


def get_paper_by_source_id(session: Session, source_id: str) -> Paper | None:
    return session.execute(select(Paper).where(Paper.source_id == source_id)).scalar_one_or_none()


def list_papers(session: Session, limit: int = 50, offset: int = 0) -> Sequence[Paper]:
    return (
        session.execute(select(Paper).order_by(Paper.id.desc()).limit(limit).offset(offset))
        .scalars()
        .all()
    )


# --- Ideas ---


def create_idea(session: Session, **kwargs) -> Idea:
    idea = Idea(**kwargs)
    session.add(idea)
    session.commit()
    session.refresh(idea)
    return idea


def get_idea(session: Session, idea_id: int) -> Idea | None:
    return session.get(Idea, idea_id)


def count_ideas(
    session: Session,
    domain: str | None = None,
    min_score: float | None = None,
    search: str | None = None,
) -> int:
    stmt = select(func.count()).select_from(Idea)
    if domain is not None:
        stmt = stmt.where(Idea.domain == domain)
    if min_score is not None:
        stmt = stmt.where(Idea.overall_score >= min_score)
    if search is not None:
        stmt = stmt.where(Idea.title.ilike(f"%{search}%"))
    return session.execute(stmt).scalar_one()


VALID_SORT_COLUMNS = {
    "score": Idea.overall_score,
    "novelty": Idea.novelty_score,
    "feasibility": Idea.feasibility_score,
    "date": Idea.created_at,
}


def list_ideas(
    session: Session,
    limit: int = 50,
    offset: int = 0,
    domain: str | None = None,
    min_score: float | None = None,
    search: str | None = None,
    sort_by: str | None = None,
    sort_order: str = "desc",
) -> Sequence[Idea]:
    stmt = select(Idea)

    # Filters
    if domain is not None:
        stmt = stmt.where(Idea.domain == domain)
    if min_score is not None:
        stmt = stmt.where(Idea.overall_score >= min_score)
    if search is not None:
        stmt = stmt.where(Idea.title.ilike(f"%{search}%"))

    # Sorting
    sort_col = VALID_SORT_COLUMNS.get(sort_by) if sort_by else None
    if sort_col is not None:
        # Nulls last: use CASE to push NULLs to the end
        nulls_last_expr = case((sort_col.is_(None), 1), else_=0)
        direction = desc if sort_order == "desc" else asc
        stmt = stmt.order_by(nulls_last_expr, direction(sort_col))
    else:
        stmt = stmt.order_by(Idea.id.desc())

    stmt = stmt.limit(limit).offset(offset)
    return session.execute(stmt).scalars().all()


def get_ideas_for_run(session: Session, run_id: int) -> Sequence[Idea]:
    """Return all ideas linked to a pipeline run via pipeline_run_id FK."""
    return (
        session.execute(
            select(Idea).where(Idea.pipeline_run_id == run_id).order_by(Idea.id.asc())
        )
        .scalars()
        .all()
    )


def count_ideas_for_run(session: Session, run_id: int) -> int:
    """Return the total count of ideas linked to a pipeline run."""
    return session.execute(
        select(func.count())
        .select_from(Idea)
        .where(Idea.pipeline_run_id == run_id)
    ).scalar_one()


def update_idea_scores(
    session: Session,
    idea_id: int,
    novelty_score: float | None = None,
    feasibility_score: float | None = None,
    novelty_report: str | None = None,
    feasibility_report: str | None = None,
) -> Idea | None:
    idea = session.get(Idea, idea_id)
    if not idea:
        return None
    if novelty_score is not None:
        idea.novelty_score = novelty_score
    if feasibility_score is not None:
        idea.feasibility_score = feasibility_score
    if novelty_report is not None:
        idea.novelty_report = novelty_report
    if feasibility_report is not None:
        idea.feasibility_report = feasibility_report
    if idea.novelty_score is not None and idea.feasibility_score is not None:
        normalized_feasibility = idea.feasibility_score / 10.0
        idea.overall_score = (idea.novelty_score + normalized_feasibility) / 2
    session.commit()
    session.refresh(idea)
    return idea


def update_idea_feedback(
    session: Session,
    idea_id: int,
    rating: int,
    notes: str | None = None,
) -> Idea | None:
    idea = session.get(Idea, idea_id)
    if not idea:
        return None
    idea.user_rating = rating
    idea.user_notes = notes
    session.commit()
    session.refresh(idea)
    return idea


# --- Proposals ---


def create_proposal(session: Session, idea_id: int, content_md: str, **kwargs) -> Proposal:
    proposal = Proposal(idea_id=idea_id, content_md=content_md, **kwargs)
    session.add(proposal)
    session.commit()
    session.refresh(proposal)
    return proposal


def get_proposal_by_idea(session: Session, idea_id: int) -> Proposal | None:
    return session.execute(select(Proposal).where(Proposal.idea_id == idea_id)).scalar_one_or_none()


# --- Pipeline Runs ---


def count_pipeline_runs(
    session: Session,
    session_id: str | None = None,
) -> int:
    stmt = select(func.count()).select_from(PipelineRun)
    if session_id is not None:
        stmt = stmt.where(PipelineRun.session_id == session_id)
    return session.execute(stmt).scalar_one()


def list_pipeline_runs(
    session: Session,
    limit: int = 20,
    offset: int = 0,
    session_id: str | None = None,
) -> Sequence[PipelineRun]:
    stmt = select(PipelineRun)
    if session_id is not None:
        stmt = stmt.where(PipelineRun.session_id == session_id)
    stmt = stmt.order_by(PipelineRun.id.desc()).limit(limit).offset(offset)
    return session.execute(stmt).scalars().all()


def list_session_ids(session: Session) -> list[dict]:
    """Return unique session_id values with run count and latest run timestamp.

    Returns list of dicts: [{session_id, run_count, latest_run_at}].
    Only includes runs where session_id is not NULL.
    """
    stmt = (
        select(
            PipelineRun.session_id,
            func.count().label("run_count"),
            func.max(PipelineRun.created_at).label("latest_run_at"),
        )
        .where(PipelineRun.session_id.isnot(None))
        .group_by(PipelineRun.session_id)
        .order_by(func.max(PipelineRun.created_at).desc())
    )
    rows = session.execute(stmt).all()
    return [
        {
            "session_id": row.session_id,
            "run_count": row.run_count,
            "latest_run_at": str(row.latest_run_at),
        }
        for row in rows
    ]


def create_pipeline_run(session: Session, **kwargs) -> PipelineRun:
    run = PipelineRun(**kwargs)
    session.add(run)
    session.commit()
    session.refresh(run)
    return run


def get_pipeline_run(session: Session, run_id: int) -> PipelineRun | None:
    return session.get(PipelineRun, run_id)


def update_pipeline_run(
    session: Session,
    run_id: int,
    status: str | None = None,
    current_stage: str | None = None,
    error_message: str | None = None,
) -> PipelineRun | None:
    run = session.get(PipelineRun, run_id)
    if not run:
        return None
    if status is not None:
        run.status = status
    if current_stage is not None:
        run.current_stage = current_stage
        completed = json.loads(run.stages_completed)
        if current_stage not in completed:
            completed.append(current_stage)
            run.stages_completed = json.dumps(completed)
    if error_message is not None:
        run.error_message = error_message
    from datetime import datetime, timezone

    if status == "completed":
        run.completed_at = datetime.now(timezone.utc)
    session.commit()
    session.refresh(run)
    return run


# --- Research Gaps ---


def create_gap(session: Session, **kwargs) -> ResearchGapDB:
    gap = ResearchGapDB(**kwargs)
    session.add(gap)
    session.commit()
    session.refresh(gap)
    return gap


def get_gap(session: Session, gap_id: int) -> ResearchGapDB | None:
    return session.get(ResearchGapDB, gap_id)


def list_gaps_by_run(session: Session, run_id: int) -> Sequence[ResearchGapDB]:
    return (
        session.execute(
            select(ResearchGapDB)
            .where(ResearchGapDB.pipeline_run_id == run_id)
            .order_by(ResearchGapDB.confidence.desc())
        )
        .scalars()
        .all()
    )


def count_gaps_by_run(session: Session, run_id: int) -> int:
    return session.execute(
        select(func.count())
        .select_from(ResearchGapDB)
        .where(ResearchGapDB.pipeline_run_id == run_id)
    ).scalar_one()


def count_ideas_for_gap(session: Session, gap_title: str) -> int:
    """Count ideas whose source_gap_ids JSON contains the given gap title.

    Uses parameterized LIKE query (HB-01) — the gap title is passed as a
    bound parameter, never interpolated into SQL.
    """
    stmt = (
        select(func.count())
        .select_from(Idea)
        .where(Idea.source_gap_ids.isnot(None))
        .where(Idea.source_gap_ids.ilike(f"%{gap_title}%"))
    )
    return session.execute(stmt).scalar_one()

"""Database engine and session management.

Supports both SQLite (default) and PostgreSQL via the DATABASE_URL setting.
PostgreSQL URLs (postgresql:// or postgresql+psycopg2://) get connection pooling
with pre-ping; SQLite uses the default StaticPool-less mode.
"""

from contextlib import contextmanager
from typing import Any

from sqlalchemy import create_engine
from sqlalchemy.orm import DeclarativeBase, sessionmaker
from sqlalchemy.pool import QueuePool

from backend.config import get_settings


class Base(DeclarativeBase):
    """SQLAlchemy declarative base."""


_engine = None
_session_factory = None


def _is_postgresql(url: str) -> bool:
    """Return True if the database URL targets PostgreSQL."""
    return url.startswith("postgresql://") or url.startswith("postgresql+")


def _build_engine_kwargs(url: str, debug: bool) -> dict[str, Any]:
    """Build keyword arguments for ``create_engine`` based on the URL scheme."""
    kwargs: dict[str, Any] = {"echo": debug}
    if _is_postgresql(url):
        kwargs.update(
            poolclass=QueuePool,
            pool_size=5,
            max_overflow=10,
            pool_pre_ping=True,
            pool_recycle=300,
        )
    return kwargs


def create_db_engine():
    """Create a new SQLAlchemy engine from the current settings.

    Uses a connection pool for PostgreSQL and plain mode for SQLite so that
    the default ``sqlite:///./data/elephant_rock.db`` works without extra deps.
    """
    settings = get_settings()
    kwargs = _build_engine_kwargs(settings.database_url, settings.debug)
    return create_engine(settings.database_url, **kwargs)


def _get_engine():
    global _engine
    if _engine is None:
        _engine = create_db_engine()
    return _engine


def _get_session_factory():
    global _session_factory
    if _session_factory is None:
        _session_factory = sessionmaker(bind=_get_engine(), expire_on_commit=False)
    return _session_factory


def create_session_factory():
    return _get_session_factory()


def init_db():
    """Create all tables."""
    Base.metadata.create_all(_get_engine())


@contextmanager
def get_session():
    """Provide a transactional scope around a series of operations."""
    session = _get_session_factory()()
    try:
        yield session
    except Exception:
        session.rollback()
        raise
    finally:
        session.close()

